package com.ems.controller; import com.ems.dao.EmployeeDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; @WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{EmployeeDAO d=new EmployeeDAO();r.setAttribute("total",d.count());r.setAttribute("active",d.activeCount());r.setAttribute("departments",d.departmentCount());r.setAttribute("recent",d.recentCount());r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}catch(Exception e){getServletContext().log("Dashboard failed",e);r.setAttribute("error","Dashboard data is temporarily unavailable.");r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}}}
